#!/usr/bin/env python3
"""Authored explanations and planar scenes for 2023 Atanasyan III, points24–30.

Source images pp53–68 were read directly; these original explanations and
coordinate checks are authoring inputs, never independent review approval.
"""
from copy import deepcopy
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DEST = ROOT / 'geometry-course/textbook'
THEORY, QUESTIONS, MODELS = [], [], []

def view(points=(), segments=(), **kw):
    return dict(label=kw.pop('label', 'Условие'), points=list(points),
                segments=[list(p) for p in segments], **kw)

def arc(o, a, b, marks=0, radius=7):
    return dict(vertex=o, **{'from': a, 'to': b}, marks=marks, radius=radius)

def eq(a,b,marks=1): return dict(a=a,b=b,marks=marks)
def right(a,o,b): return dict(a=a,vertex=o,b=b)
def ck(kind,**kw): return dict(type=kind,**kw)
def par(a,b,c,d): return ck('parallel',segments=[[a,b],[c,d]])
def perp(a,b,c,d): return ck('perpendicular',segments=[[a,b],[c,d]])
def equal(*pairs): return ck('equalLength',segments=[list(p) for p in pairs])
def col(*ps): return ck('collinear',points=list(ps))
def angle(a,o,b,d): return ck('angle',points=[a,o,b],degrees=d)
def step(prompt,explanation,reason,refs):
    return dict(prompt=prompt,explanation=explanation,justification=reason,theoryPoints=list(refs))

def model(points,initial,scenes,checks=(),cases=(),labels=None,offsets=None,label_only=()):
    vv={'neutral':deepcopy(initial)}
    for i,s in enumerate(scenes,1):
        vv[f'step-{i}']=deepcopy(s);vv[f'step-{i}']['label']=f'Шаг {i}'
    for i,s in enumerate(cases,1):vv[f'case-{i}']=deepcopy(s)
    m=dict(points={k:[round(float(v[0]),9),round(float(v[1]),9),0] for k,v in points.items()},
           edges=[],planar=True,bounds=[0,0,100,70],views=vv,checks=list(checks),
           description='Отдельный чертёж к этому вопросу. Вспомогательные линии и отметки появляются при обосновании; случаи рассматриваются отдельно.')
    if labels:m['labels']=labels
    if offsets:m['labelOffsets']=offsets
    if label_only:m['labelOnly']=list(label_only)
    return m

def add(collection,number,title,pages,statement,rows,answer,m,notes=()):
    assert len(rows)==sum(k.startswith('step-') for k in m['views']), (collection,number,len(rows))
    did={'steps':[{k:v for k,v in s.items() if k!='explanation'} for s in rows]}
    record=dict(number=number,title=title,printedPages=pages,pdfPages=[p+1 for p in pages],
                statement=statement,steps=[s['explanation'] for s in rows],answer=answer,
                didactics=did,sourceVerified=True,mathVerified=True,notes=list(notes))
    (THEORY if collection=='theory' else QUESTIONS).append(record)
    MODELS.append(dict(chapter=3,collection=collection,number=number,part='single',model=m,didactics=deepcopy(did)))
    return record

def labelled_case(v,label,unlock):
    z=deepcopy(v);z.update(label=label,availableFromStep=unlock);return z

# A clean transversal; helper points remain unlabeled unless needed by a proof.
P={'A':(60,52),'B':(40,18),'U':(12,52),'V':(88,52),'W':(12,18),'X':(88,18),
   'T':(67.058823529,64),'S':(32.941176471,6),'O':(50,35),'H':(50,52),'H1':(50,18),
   'a':(88,57),'b':(88,23),'c':(73,64),
   'n1':(48,60),'n2':(71,59),'n3':(73,45),'n4':(49,44),
   'n5':(27,26),'n6':(51,26),'n7':(53,11),'n8':(28,10)}
LINES=[['U','V'],['W','X'],['S','T']]
LABELS={'H1':'H₁',**{f'n{i}':str(i) for i in range(1,9)}}
OFF={'A':(3,5),'B':(-3,-5),'O':(-6,0),'H':(-4,5),'H1':(3,-5),
     'U':(-2,4),'V':(0,-6),'W':(-2,-4),'X':(2,-4),'T':(-5,-2)}
