SAME=view(['A','B','a','b','V','X'],lines=LINES,angleArcs=[arc('A','V','B'),arc('B','X','A')])
COR_ALT=deepcopy(COR);COR_ALT['points']+=['U'];COR_ALT['angleArcs']+=[arc('A','U','B',1)]
SAME_ALT=deepcopy(SAME);SAME_ALT['points']+=['U'];SAME_ALT['angleArcs']=[arc('A','V','B'),arc('A','U','B',1),arc('B','X','A',1)]
TRANS_CHECKS=[par('U','V','W','X'),col('S','B','O','A','T'),col('U','H','A','V'),col('W','B','H1','X')]

def trans_model(scenes,initial=BASE,cases=(),extra=()):
    return model(P,initial,scenes,TRANS_CHECKS+list(extra),cases,LABELS,OFF,LABEL_ONLY)

def numbered_view(numbers):
    return view(['a','b','c']+[f'n{i}' for i in numbers],lines=LINES)

# 24: parallelism belongs to the supporting lines, not to two short strokes.
