perpendicular=view(['A','B','C','D','M','N'],[['M','N']],lines=[['A','B'],['C','D']],rightAngles=[right('B','M','N'),right('M','N','D')])
definition_rows=[
 step('Какие прямые называют параллельными?','Две различные прямые одной плоскости параллельны, когда у них нет общей точки. Запись AB ∥ CD относится ко всем продолжениям этих прямых.','Определение параллельности',[1,24]),
 step('Когда параллельны отрезки или лучи?','Отрезки AB и CD параллельны, если параллельны содержащие их прямые. Так же определяем параллельность лучей и параллельность отрезка прямой.','Переход к содержащим прямым',[24]),
 step('Достаточно ли того, что отрезки не встретились?','Нет. Короткие отрезки могут не иметь общей точки, хотя продолжения их прямых пересекутся. Поэтому смотрим на прямые, а не только на нарисованные отрезки.','Определение и продолжение отрезка до прямой',[1,24]),
 step('Как получить уже известный пример?','Две разные прямые, перпендикулярные одной прямой, не пересекаются. Это доказано в п.12; теперь можем назвать их параллельными.','Ранее доказанное свойство перпендикулярных прямых',[12,24])]
definition_model=model(p,parallel,[parallel,parallel,separate,perpendicular],
    [par('A','B','C','D'),perp('M','N','A','B'),perp('M','N','C','D')],
    [labelled_case(separate,'Отрезки без общей точки',3)],label_only=['a','b'])
add('theory',24,'Параллельные прямые, отрезки и лучи',[53,54],
    'Разберём определение параллельности и узнаем, почему непересекающихся отрезков недостаточно.',
    definition_rows,'Параллельные прямые одной плоскости не имеют общей точки; отрезки и лучи сравниваем по содержащим их прямым.',definition_model)

# A full elementary proof of the alternate-interior criterion, including90°.
MID=deepcopy(ALT);MID['points']+=['O'];MID['equalSegments']=[eq('A','O'),eq('O','B')]
DROP=deepcopy(MID);DROP['points']+=['H'];DROP['segments']=[['O','H']];DROP['rightAngles']=[right('A','H','O')]
COPY=deepcopy(DROP);COPY['points']+=['H1'];COPY['segments']+=[['O','H1']];COPY['equalSegments']+=[eq('A','H',2),eq('B','H1',2)]
SAS=deepcopy(COPY);SAS['highlightSegments']=[['A','O'],['A','H'],['B','O'],['B','H1']]
