criterion_rows=[
 step('Что дано и что нужно доказать?','Прямые a и b пересечены AB. Накрест лежащие углы ∠UAB и ∠ABX равны. Нужно доказать a ∥ b.','Условие признака; расположение накрест лежащих углов',[25]),
 step('Что делать, если оба угла прямые?','Тогда a ⟂ AB и b ⟂ AB. Две разные прямые, перпендикулярные одной, параллельны. Этот случай закончен.','Свойство из п.12 и определение',[12,24]),
 step('С чего начать непрямой случай?','Отметим середину O отрезка AB и опустим OH ⟂ a. Тогда AO = OB. Здесь H отличается от A, потому что рассматриваем непрямые углы.','Середина и перпендикуляр из точки',[6,16]),
 step('Как построить вторую маленькую фигуру?','На b выберем H₁ с BH₁ = AH так, чтобы лучи AH и BH₁ лежали по разные стороны секущей AB. Соединим O с H₁.','Откладывание отрезка; данная пара накрест лежащих углов',[7,25]),
 step('По какому признаку сравнить треугольники?','В △AOH и △BOH₁ имеем AO = BO, AH = BH₁ и ∠OAH = ∠OBH₁. Последние углы равны по условию либо как дополнения данных углов до 180°. Поэтому △AOH = △BOH₁ по двум сторонам и углу между ними.','Первый признак равенства; смежные углы',[11,15]),
 step('Почему H, O и H₁ лежат на одной прямой?','Из равенства треугольников ∠AOH = ∠BOH₁. Луч, противоположный OH, образует с OB такой же угол по свойству вертикальных углов. Он и OH₁ находятся в одной полуплоскости от AB, поэтому совпадают: H, O, H₁ коллинеарны.','Вертикальные углы; единственность откладывания угла',[9,11]),
 step('Почему вторая прямая тоже перпендикулярна HH₁?','В равных треугольниках ∠BH₁O = ∠AHO =90°. Поэтому b ⟂ HH₁. По построению a ⟂ HH₁.','Соответствующие углы равных треугольников',[14,15]),
 step('Как закончить доказательство?','Разные прямые a и b перпендикулярны одной прямой HH₁, следовательно, они параллельны. Непрямой случай тоже доказан.','Свойство перпендикулярных прямых',[12,24])]

