def combine_models(first,second):
    m=deepcopy(first);m['points'].update(deepcopy(second['points']));m['checks']+=deepcopy(second['checks'])
    for field in ['labels','labelOffsets']:
        m.setdefault(field,{}).update(deepcopy(second.get(field,{})))
    count=sum(k.startswith('step-') for k in first['views'])
    case_count=sum(k.startswith('case-') for k in first['views'])
    for k,v in second['views'].items():
        if k.startswith('step-'):
            i=count+int(k.split('-')[1]);m['views'][f'step-{i}']={**deepcopy(v),'label':f'Шаг {i}'}
        elif k!='neutral':
            case_count+=1
            z=deepcopy(v);z['availableFromStep']=z.get('availableFromStep',0)+count;m['views'][f'case-{case_count}']=z
    return m

